tool_schemas.search_workflows:
exec tool declaration:
```ts
declare const tools: { mcp__n8n__search_workflows(args: {
  // Filter by folder. Pass a parentFolderId from an earlier result to find a workflow's siblings, or — when search_folders is available — use it to resolve a folder name to an id first. Pass "0" for workflows that sit at the project root rather than in a folder.
  folderId?: string;
  // Whether a folderId search also covers that folder's subfolders (default: true). Set false to match only workflows directly inside the folder. Ignored when folderId is "0", which always matches the project root only.
  includeSubfolders?: boolean;
  // Limit the number of results (max 200)
  limit?: number;
  projectId?: string;
  // Filter by name or description
  query?: string;
  // Sort order for results (default: updatedAt:desc). Use updatedAt:desc to find the most recently edited workflows first.
  sortBy?: "updatedAt:desc" | "updatedAt:asc" | "createdAt:desc" | "createdAt:asc" | "name:asc" | "name:desc";
  // Filter by tag names (AND semantics — workflow must have all).
  tags?: Array<string>;
}): Promise<CallToolResult<{
  // Total number of workflows that match the filters
  count: number;
  // List of workflows matching the query
  data: Array<{
  // Whether the workflow is active
  active: boolean | null;
  // Whether the workflow is visible to MCP tools
  availableInMCP: boolean;
  // The ISO timestamp when the workflow was created
  createdAt: string | null;
  // The description of the workflow
  description?: string | null;
  // The unique identifier of the workflow
  id: string;
  // The name of the workflow
  name: string | null;
  // The id of the folder holding the workflow, or null when it sits at the project root. Pass it back as folderId to find related workflows.
  parentFolderId: string | null;
  // Tags assigned to the workflow
  tags: Array<{ id: string; name: string; [key: string]: unknown; }>;
  // The number of triggers associated with the workflow
  triggerCount: number | null;
  // ISO timestamp the workflow definition was last saved. Use this to identify recently edited workflows.
  updatedAt: string | null;
  [key: string]: unknown;
}>;
  // Error message explaining why the search failed. Present only on failure.
  error?: string;
}>>; };
```

tool_schemas.get_workflow_details:
exec tool declaration:
```ts
declare const tools: { mcp__n8n__get_workflow_details(args: {
  // Level of detail to return. 'full' (default) includes the complete workflow payload. 'execution' returns only the workflow metadata and trigger information needed to run it — prefer it when the goal is just to execute the workflow via execute_workflow.
  detailLevel?: "full" | "execution";
  // The ID of the workflow to retrieve
  workflowId: string;
}): Promise<CallToolResult<{
  // Trigger info for the published (active) version, which production executions via execute_workflow run. Only present when it differs from the draft's triggerInfo.
  activeVersionTriggerInfo?: string;
  // Human-readable instructions describing how to trigger the workflow, based on the current draft (what manual executions run)
  triggerInfo: string;
  // Sanitized workflow data safe for MCP consumption
  workflow: {
  active: boolean;
  // Published (active) workflow graph. Null when the workflow has no published version. Only included when detailLevel is 'full'.
  activeVersion?: {
  // The published version is identical to the current draft — use the top-level nodes, connections and nodeGroups.
  sameAsDraft: true;
} | {
  connections: { [key: string]: unknown; };
  // Node groups in the active version
  nodeGroups: Array<{
  description?: string;
  id: string;
  name: string;
  // Names of the member nodes, matching the update_workflow group operations.
  nodeNames: Array<string>;
}>;
  nodes: Array<{
  // Credentials assigned to the node, keyed by credential type (e.g. "slackApi"). Reuse these when adding nodes for the same service to this workflow.
  credentials?: { [key: string]: {
  // The credential ID, used to reference this credential in write operations
  id: string;
  // The credential name
  name: string;
}; };
  name: string;
  type: string;
  [key: string]: unknown;
}>;
  sameAsDraft: false;
} | null;
  // The active workflow version ID, if available
  activeVersionId: string | null;
  // Whether the user has permission to execute this workflow
  canExecute: boolean;
  // Only included when detailLevel is 'full'.
  connections?: { [key: string]: unknown; };
  createdAt: string | null;
  // The description of the workflow
  description?: string;
  id: string;
  isArchived: boolean;
  // Only included when detailLevel is 'full'.
  meta?: unknown | null;
  name: string | null;
  // Number of nodes in the workflow, reported even when detailLevel omits them
  nodeCount: number;
  // Node groups in the workflow. Only included when detailLevel is 'full'.
  nodeGroups?: Array<{
  description?: string;
  id: string;
  name: string;
  // Names of the member nodes, matching the update_workflow group operations.
  nodeNames: Array<string>;
}>;
  // Only included when detailLevel is 'full'.
  nodes?: Array<{
  // Credentials assigned to the node, keyed by credential type (e.g. "slackApi"). Reuse these when adding nodes for the same service to this workflow.
  credentials?: { [key: string]: {
  // The credential ID, used to reference this credential in write operations
  id: string;
  // The credential name
  name: string;
}; };
  name: string;
  type: string;
  [key: string]: unknown;
}>;
  parentFolderId: string | null;
  // User permissions for this workflow
  scopes: Array<string>;
  settings?: unknown | null;
  tags: Array<{ id: string; name: string; [key: string]: unknown; }>;
  triggerCount: number;
  updatedAt: string | null;
  // The current workflow version ID
  versionId: string;
  [key: string]: unknown;
};
}>>; };
```

